FOLDERS = ('native/include', 'native/src', 'native/tests')


def _sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def check(rel: str, data: bytes) -> None:
    state, sha, why = FILES[rel]
    assert _sha(data) == sha, (rel, state, 'differs from the sealed bytes (edited after sealing; regenerate with a reason)')


def verify() -> dict:
    root = ROOT
    for rel in FILES:
        path = root / rel
        assert path.is_file(), (rel, 'sealed file is missing')
        check(rel, path.read_bytes())
    for folder in FOLDERS:
        for path in (root / folder).glob('*.*'):
            rel = path.relative_to(root).as_posix()
            assert rel in FILES, (rel, 'new file in a sealed folder, not in the seal')
    return {s: sum(1 for v in FILES.values() if v[0] == s) for s in ('unchanged', 'changed', 'added')}


# Silent edits (a constant or a condition changed without resealing): each must fail check().
SILENT_EDITS = [
    ('native/include/Timer.h', 'inline constexpr float kFlowMagickaShare = 0.8f;', 'inline constexpr float kFlowMagickaShare = 0.85f;'),
    ('native/include/Timer.h', 'inline constexpr float kDomainRadius = 210.0f;', 'inline constexpr float kDomainRadius = 211.0f;'),
    ('native/include/StatusEngine.h', 'engine.Cast(Who::kTarget, spawn, 0.0f, 1.0f);', 'engine.Cast(Who::kTarget, spawn, 0.5f, 1.0f);'),
    ('native/src/Plugin.cpp', 'return ui && (ui->GameIsPaused() || ui->IsMenuOpen(RE::LoadingMenu::MENU_NAME));',
     'return ui && ui->GameIsPaused();'),
    ('build/fix25_records.py', 'DOMAIN_MAX_SECONDS = 24', 'DOMAIN_MAX_SECONDS = 23'),
    ('build/fix25_reference.py', "UPKEEP_BASE, UPKEEP_DARK, UPKEEP_RELIEF = 1.0, 2.0, 0.7", "UPKEEP_BASE, UPKEEP_DARK, UPKEEP_RELIEF = 1.0, 2.0, 0.6"),
]


def self_check() -> dict:
    counts = verify()
    caught = []
    for rel, old, new in SILENT_EDITS:
        data = (ROOT / rel).read_bytes()
        assert old.encode('utf-8') in data, (rel, old)
        try:
            check(rel, data.replace(old.encode('utf-8'), new.encode('utf-8'), 1))
        except AssertionError:
            caught.append(rel)
            continue
        raise AssertionError(('silent edit not caught', rel, old))
    return dict(counts, silent_edits_caught=caught)
